(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-868":{scenario:{company:"Cánh Diều Education Consulting",supervisor:{name:"Phan Đức Thịnh",role:{vi:"Giám đốc Tư vấn Du học",en:"Head of Study Abroad Counseling"}},ref_code:"SA-9056",title:{vi:"Đúng loại thị thực. Đúng tài chính. Đúng sự thật.",en:"Right visa. Right funds. Right truth."},brief:{vi:"Học sinh hồ sơ SA-9056 được một đại học Mỹ nhận vào chương trình cử nhân 4 năm toàn thời gian và cấp mẫu I-20. Chi phí năm đầu trên I-20: học phí 27.850 USD, sinh hoạt 14.600 USD, bảo hiểm và tài liệu 2.350 USD; học bổng của trường 8.500 USD (số liệu mô phỏng). Đối chiếu hồ sơ nháp với danh mục hồ sơ đã duyệt, sửa loại thị thực cần xin và số tiền gia đình phải chứng minh cho năm đầu (USD), rồi lập báo cáo có căn cứ.",en:"Student file SA-9056 has been admitted by a US university to a 4-year full-time bachelor's program and issued Form I-20. First-year costs on the I-20: tuition 27,850 USD, living 14,600 USD, insurance and books 2,350 USD; university scholarship 8,500 USD (training data). Compare the draft file with the approved checklist, correct the visa type to apply for and the first-year funds the family must document (USD), then write an evidence-based report."},reference_title:{vi:"Danh mục hồ sơ thị thực & bảng tài chính đã duyệt · SA-9056",en:"Approved visa checklist & funding sheet · SA-9056"},fields:[{id:"VISA_TYPE",label:{vi:"Loại thị thực cần xin",en:"Visa type to apply for"},initial:"J-1",expected:"F-1",choices:["J-1","F-1","M-1"],reference:"Danh mục hồ sơ thị thực",hint:{vi:"Xem trường cấp mẫu giấy tờ nào: I-20 cho chương trình học thuật hay DS-2019 cho chương trình trao đổi.",en:"Check which form the school issued: an I-20 for academic study or a DS-2019 for an exchange program."}},{id:"FUNDS_USD",label:{vi:"Số tiền cần chứng minh năm đầu (USD)",en:"First-year funds to document (USD)"},initial:"33950",expected:"36300",reference:"Bảng tài chính năm đầu",ref_value:{vi:"Học phí 27.850; sinh hoạt 14.600; bảo hiểm và tài liệu 2.350; học bổng 8.500 USD",en:"Tuition 27,850; living 14,600; insurance and books 2,350; scholarship 8,500 USD"},hint:{vi:"Cộng đủ mọi khoản chi phí ghi trên I-20 trước khi trừ học bổng đã được xác nhận.",en:"Add every cost line on the I-20 before deducting the confirmed scholarship."}}],sop32:{vi:"Số tiền cần chứng minh năm đầu = tổng chi phí ước tính trên I-20 (học phí + sinh hoạt + bảo hiểm, tài liệu) - học bổng hoặc tài trợ đã có văn bản xác nhận.",en:"First-year funds to document = total estimated costs on the I-20 (tuition + living + insurance and books) - scholarships or funding confirmed in writing."},context:{label:"CRM HỒ SƠ / SA-9056",metrics:[{label:{vi:"Mẫu giấy tờ trường cấp",en:"Form issued by school"},value:"I-20"},{label:{vi:"Tổng chi phí I-20",en:"Total I-20 costs"},value:"44,800 USD"},{label:{vi:"Học bổng mô phỏng",en:"Training scholarship"},value:"8,500 USD"}]},crisis:{vi:"Phụ huynh nói: “Bên dịch vụ làm giúp sổ tiết kiệm 40.000 USD trong một tuần, em cứ nộp kèm hồ sơ.” Trưởng nhóm kinh doanh nhắn thêm: “Kệ đi, nhiều nhà làm vậy, mất khách là mất hoa hồng.”",en:"The parent says: “A service can make us a 40,000 USD savings book in a week, just attach it to the file.” The sales lead adds: “Let it go, many families do it, losing the client means losing commission.”"},options:{safe:{vi:"Từ chối nộp giấy tờ tài chính không xác thực, giải thích rủi ro bị từ chối và cấm nhập cảnh, báo Giám đốc Tư vấn; hướng dẫn nguồn hợp lệ như tiền gửi thật, người bảo trợ, học bổng, khoản vay có hồ sơ.",en:"Refuse to submit non-genuine financial documents, explain the risk of refusal and entry bans, inform the Head of Counseling; guide the family to genuine savings, sponsors, scholarships or documented loans."},shortcut:{vi:"Nộp sổ tiết kiệm từ bên dịch vụ cho kịp lịch phỏng vấn, coi như trách nhiệm của gia đình.",en:"Submit the service's savings book to make the interview date, treating it as the family's responsibility."},wait:{vi:"Không góp ý và để gia đình tự quyết định giấy tờ tài chính nộp kèm.",en:"Say nothing and let the family decide which financial papers to attach."}},questions:{vi:["Vì sao học sinh cần thị thực F-1 và phải chứng minh 36300 USD cho năm đầu? Trình bày căn cứ từ I-20.","Hậu quả của việc nộp giấy tờ tài chính giả hoặc tạm thời là gì? Bạn tư vấn gia đình phương án hợp lệ nào?"],en:["Why does the student need an F-1 visa and 36300 USD of documented funds for year one? Cite the I-20.","What are the consequences of submitting fake or temporary financial documents? Which lawful options do you advise?"]},hints:{vi:["Đặt hồ sơ nháp cạnh danh mục hồ sơ thị thực và kiểm tra mẫu giấy tờ trường đã cấp.","Áp dụng SOP mục 3.2: cộng đủ chi phí trên I-20 rồi trừ học bổng có văn bản.","Đọc lại SOP mục 4.2: tư vấn viên không được tham gia hoặc làm ngơ trước hồ sơ gian dối; phải báo cáo và tư vấn phương án hợp lệ."],en:["Place the draft file next to the visa checklist and check which form the school issued.","Apply SOP 3.2: add all I-20 costs and then deduct the documented scholarship.","Re-read SOP 4.2: advisors must never take part in or ignore fraudulent files; escalate and advise lawful options."]}},learning:{summary:{vi:"Chuyên viên tư vấn tuyển sinh và du học quốc tế giúp học sinh, sinh viên chọn quốc gia, trường, ngành phù hợp năng lực và tài chính, xây dựng hồ sơ ứng tuyển, săn học bổng, chuẩn bị thị thực và định hướng trước khi lên đường. Công việc đòi hỏi hiểu biết hệ thống giáo dục nhiều nước, quy định thị thực cập nhật, kỹ năng tư vấn lấy học sinh làm trung tâm và chuẩn mực trung thực với hồ sơ.",en:"An academic and study abroad advisor helps students choose countries, institutions and majors that fit their ability and budget, builds applications, finds scholarships, prepares visas and runs pre-departure orientation. The role needs knowledge of many education systems, up-to-date visa rules, student-centered counseling skills and strict honesty with every file."},responsibilities:{vi:["Đánh giá học lực, ngoại ngữ, mục tiêu và ngân sách để lập danh sách trường phù hợp.","Hướng dẫn hồ sơ ứng tuyển: bảng điểm, bài luận, thư giới thiệu, chứng chỉ ngoại ngữ.","Tìm và hỗ trợ nộp học bổng, lập bảng chi phí và kế hoạch tài chính minh bạch.","Chuẩn bị hồ sơ thị thực đúng loại, luyện phỏng vấn và kiểm tra tính xác thực giấy tờ.","Định hướng trước khi đi, theo dõi học sinh sau nhập học và cập nhật quy định mới."],en:["Assess grades, language level, goals and budget to build a fitting school list.","Guide applications: transcripts, essays, recommendation letters and language certificates.","Find and support scholarship applications and build transparent cost and funding plans.","Prepare the right visa file, coach interviews and verify document authenticity.","Run pre-departure orientation, follow students after enrollment and track rule changes."]},competencies:[{name:{vi:"Hiểu biết hệ thống giáo dục quốc tế",en:"International education systems"},desc:{vi:"Nắm cấu trúc bậc học, yêu cầu đầu vào, kiểm định và cách quy đổi điểm ở các nước phổ biến.",en:"Know degree structures, entry requirements, accreditation and grade conversion in major destinations."}},{name:{vi:"Quy trình thị thực du học",en:"Student visa process"},desc:{vi:"Chọn đúng loại thị thực, giấy tờ xác nhận nhập học và chứng minh tài chính theo từng nước.",en:"Choose the right visa, admission documents and proof of funds for each country."}},{name:{vi:"Tư vấn lấy học sinh làm trung tâm",en:"Student-centered counseling"},desc:{vi:"Lắng nghe, khai thác mục tiêu thật và đưa lựa chọn khách quan, không chạy theo hoa hồng.",en:"Listen, uncover real goals and give objective options rather than chasing commission."}},{name:{vi:"Lập kế hoạch tài chính du học",en:"Study abroad financial planning"},desc:{vi:"Tính tổng chi phí, học bổng, tỷ giá và dòng tiền cho toàn khóa học.",en:"Compute total costs, scholarships, exchange rates and cash flow for the whole program."}},{name:{vi:"Liêm chính hồ sơ",en:"Application integrity"},desc:{vi:"Từ chối giấy tờ giả, bài luận viết hộ và cam kết sai sự thật; bảo vệ dữ liệu học sinh.",en:"Refuse fake documents, ghost-written essays and false statements; protect student data."}}],knowledge:{vi:["Thị thực du học Mỹ: F-1 cho chương trình học thuật và tiếng Anh (mẫu I-20), J-1 cho trao đổi (mẫu DS-2019), M-1 cho học nghề; phí SEVIS.","Thị thực Student của Anh dựa trên CAS; thị thực du học Úc subclass 500 cần CoE; Canada cấp giấy phép du học (study permit).","Nghị định 86/2021/NĐ-CP quy định việc công dân Việt Nam ra nước ngoài học tập, giảng dạy, nghiên cứu khoa học và trao đổi học thuật.","Quy định hiện hành về điều kiện kinh doanh dịch vụ tư vấn du học: đăng ký với cơ quan giáo dục, nhân sự có chứng chỉ nghiệp vụ.","Cách đọc chi phí trên giấy xác nhận nhập học, học bổng có điều kiện và quy đổi GPA giữa các thang điểm."],en:["US student visas: F-1 for academic and language study (Form I-20), J-1 for exchange (Form DS-2019), M-1 for vocational study; SEVIS fee.","The UK Student visa is based on a CAS; the Australian student visa subclass 500 needs a CoE; Canada issues a study permit.","Decree 86/2021/ND-CP on Vietnamese citizens going abroad for study, teaching, research and academic exchange.","Current rules on conditions for study abroad consulting services: registration with the education authority and certified advisors.","Reading costs on admission documents, conditional scholarships and GPA conversion between grading scales."]},tools:["Phần mềm CRM quản lý hồ sơ học sinh","Cổng nộp hồ sơ trực tuyến của các trường","Bảng tính chi phí và học bổng","Danh mục kiểm tra hồ sơ thị thực","Công cụ quy đổi điểm GPA","Lịch theo dõi hạn nộp hồ sơ"],kpis:{vi:["Tỷ lệ học sinh nhận thư mời nhập học từ trường trong danh sách phù hợp.","Tỷ lệ đậu thị thực ngay lần đầu.","Tổng giá trị học bổng đạt được trên mỗi học sinh.","Mức hài lòng của học sinh, phụ huynh sau 6 tháng nhập học."],en:["Share of students admitted to schools on their fit list.","First-time visa approval rate.","Total scholarship value won per student.","Student and parent satisfaction 6 months after enrollment."]},day:[{time:"08:30",vi:"Rà soát lịch hạn nộp hồ sơ, thư phản hồi của trường và cập nhật CRM.",en:"Review application deadlines and school replies and update the CRM."},{time:"10:00",vi:"Tư vấn trực tiếp gia đình mới: đánh giá năng lực, mục tiêu và ngân sách.",en:"Meet a new family to assess ability, goals and budget."},{time:"13:30",vi:"Góp ý bài luận, kiểm tra bảng điểm dịch thuật và thư giới thiệu.",en:"Give essay feedback and check translated transcripts and recommendation letters."},{time:"15:30",vi:"Lập bảng tài chính, kiểm tra giấy tờ chứng minh và luyện phỏng vấn thị thực.",en:"Build the funding sheet, check proof of funds and coach the visa interview."},{time:"17:30",vi:"Cập nhật thay đổi chính sách thị thực và chia sẻ với nhóm tư vấn.",en:"Track visa policy changes and brief the counseling team."}],mistakes:{vi:["Nhầm loại thị thực, ví dụ xin J-1 trong khi trường cấp I-20 cho chương trình cử nhân.","Bỏ sót khoản bảo hiểm, tài liệu hoặc trừ học bổng chưa được xác nhận khi tính số tiền cần chứng minh.","Làm ngơ hoặc hỗ trợ giấy tờ tài chính giả, khiến học sinh bị từ chối và có thể bị cấm nhập cảnh."],en:["Choosing the wrong visa, such as J-1 when the school issued an I-20 for a bachelor's program.","Missing insurance or books, or deducting unconfirmed scholarships, when computing required funds.","Ignoring or helping with fake financial documents, leading to refusal and possible entry bans."]},career:[{vi:"Nhân viên hỗ trợ hồ sơ du học",en:"Application support officer"},{vi:"Chuyên viên tư vấn du học",en:"Study abroad advisor"},{vi:"Trưởng nhóm tư vấn tuyển sinh quốc tế",en:"International admissions team lead"},{vi:"Giám đốc tư vấn du học & đối tác quốc tế",en:"Director of study abroad & international partnerships"}],glossary:[{term:"I-20",vi:"Giấy xác nhận đủ điều kiện nhập học do trường Mỹ cấp, căn cứ xin thị thực F-1 hoặc M-1.",en:"Certificate of eligibility issued by a US school, used to apply for an F-1 or M-1 visa."},{term:"SEVIS",vi:"Hệ thống quản lý thông tin sinh viên và khách trao đổi của Mỹ; người xin thị thực phải nộp phí SEVIS.",en:"The US student and exchange visitor information system; applicants must pay the SEVIS fee."},{term:"CAS",vi:"Mã xác nhận chấp nhận học do trường Anh cấp để xin thị thực Student.",en:"Confirmation of Acceptance for Studies issued by a UK institution for the Student visa."},{term:"Proof of funds",vi:"Bằng chứng tài chính hợp lệ cho thấy đủ khả năng chi trả học phí và sinh hoạt.",en:"Genuine evidence of the ability to pay tuition and living costs."},{term:"Conditional offer",vi:"Thư mời nhập học có điều kiện, ví dụ phải đạt điểm ngoại ngữ hoặc tốt nghiệp đúng hạn.",en:"An admission offer subject to conditions such as a language score or graduation on time."}],quiz:[{q:{vi:"Chi phí năm đầu trên I-20 là 52.000 USD, học bổng có xác nhận 12.000 USD. Gia đình cần chứng minh bao nhiêu?",en:"First-year I-20 costs are 52,000 USD with a confirmed 12,000 USD scholarship. How much must the family document?"},options:{vi:["52.000 USD","64.000 USD","12.000 USD","40.000 USD"],en:["52,000 USD","64,000 USD","12,000 USD","40,000 USD"]},answer:3,explain:{vi:"Số cần chứng minh = 52.000 - 12.000 = 40.000 USD.",en:"Funds to document = 52,000 - 12,000 = 40,000 USD."}},{q:{vi:"Trường Mỹ cấp DS-2019 cho chương trình trao đổi một học kỳ. Học sinh cần xin thị thực nào?",en:"A US school issues a DS-2019 for a one-semester exchange. Which visa does the student need?"},options:{vi:["F-1","J-1","M-1","B-2"],en:["F-1","J-1","M-1","B-2"]},answer:1,explain:{vi:"Mẫu DS-2019 dùng cho khách trao đổi diện J-1.",en:"Form DS-2019 is used for J-1 exchange visitors."}},{q:{vi:"Phụ huynh muốn dùng dịch vụ làm sổ tiết kiệm tạm thời để chứng minh tài chính. Bạn làm gì?",en:"Parents want a service to create a temporary savings book as proof of funds. What do you do?"},options:{vi:["Từ chối, giải thích rủi ro, báo cáo và hướng dẫn nguồn tài chính hợp lệ","Đồng ý vì là trách nhiệm của gia đình","Giới thiệu dịch vụ uy tín hơn","Im lặng để giữ khách"],en:["Refuse, explain the risks, escalate and guide genuine funding sources","Agree since it is the family's responsibility","Recommend a more reliable service","Stay silent to keep the client"]},answer:0,explain:{vi:"Giấy tờ tài chính không xác thực là gian dối hồ sơ thị thực; tư vấn viên phải từ chối và hướng dẫn phương án hợp pháp.",en:"Non-genuine financial documents are visa fraud; advisors must refuse and guide lawful options."}},{q:{vi:"Để xin thị thực Student của Anh, học sinh cần mã xác nhận nào từ trường?",en:"To apply for a UK Student visa, which reference does the student need from the institution?"},options:{vi:["I-20","CoE","CAS","DS-2019"],en:["I-20","CoE","CAS","DS-2019"]},answer:2,explain:{vi:"Trường Anh cấp CAS; CoE dùng cho Úc, I-20 và DS-2019 dùng cho Mỹ.",en:"UK institutions issue a CAS; a CoE is for Australia, while the I-20 and DS-2019 are for the US."}}],tools_en:["CRM for student application management","University online application portals","Cost and scholarship spreadsheets","Visa document checklist","GPA conversion tools","Application deadline tracking calendar"]}}})})(window.KKR);
